INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q13600791', 'Battle of Gol-Zarriun', 'The Battle of Gol-Zarriun, also known as Battle of Bukhara, took place around 563 when the Sasanian Empire and the First Turkic Khaganate allied with each other against the Hephthalite Empire.', 560, NULL, NULL, NULL, NULL, NULL, 'year', '560', 48, 'https://en.wikipedia.org/wiki/Battle_of_Gol-Zarriun'),
  ('Q4870429', 'Battle of Baykand', 'The Battle of Baykand was fought in 729 between the Turkic Türgesh khaganate and its Soghdian allies and the Arabs of the Umayyad Caliphate at Baykand, a town near Bukhara in Transoxiana (in modern Uzbekistan). The Arab army, under the governor of Khurasan Ashras ibn Abdallah al-Sulami, campaigned across the Oxus River to suppress a large-scale rebellion of the subject Soghdian princes that had broken out the previous year and received Türgesh support.', 729, NULL, NULL, NULL, NULL, NULL, 'year', '729', 45, 'https://en.wikipedia.org/wiki/Battle_of_Baykand'),
  ('Q3950956', 'Battle of Qatwan', 'The Battle of Qatwan (Chinese: 卡特萬之戰) was fought in September 1141 between the Qara Khitai (Western Liao dynasty) and the Seljuk Empire and its vassal-state the Kara-Khanid Khanate. The battle ended in a decisive defeat for the Seljuks, signaling the beginning of the end of the Great Seljuk Empire.', 1141, 9, 9, NULL, NULL, NULL, 'day', '9 September 1141', 56, 'https://en.wikipedia.org/wiki/Battle_of_Qatwan'),
  ('Q7510363', 'Siege of Samarkand', 'The siege of Samarkand took place in March 1220 after Genghis Khan, founder of the Mongol Empire, had launched a multi-pronged invasion of the Khwarazmian Empire, ruled by Shah Muhammad II. The Mongols had laid siege to the border town of Otrar, but finding its defences obdurate, a large force commanded by Genghis and his youngest son Tolui detached from the vanguard and set off southwards, towards Transoxiana. Samarkand was the Shah''s capital and the pivot of his defence — the city''s garrison was large and its battlements were one of the strongest in the empire.', 1220, NULL, NULL, NULL, NULL, NULL, 'year', '1220', 47, 'https://en.wikipedia.org/wiki/Siege_of_Samarkand_(1220)'),
  ('Q110970851', 'Siege of Bukhara (1220)', 'The siege of Bukhara took place in February 1220, during the Mongol invasion of the Khwarazmian Empire. Genghis Khan, ruler of the Mongol Empire, had launched a multi-pronged assault on the Khwarazmian Empire ruled by Shah Muhammad II. While the Shah planned to defend his major cities individually, the Mongols laid siege to the border town of Otrar, and struck further into Khwarazmia.', 1220, 2, NULL, NULL, NULL, NULL, 'month', 'February 1220', 57, 'https://en.wikipedia.org/wiki/Siege_of_Bukhara'),
  ('Q111181659', 'Siege of Gurganj', 'The siege of Gurganj occurred during the Mongol invasion of the Khwarazmian Empire. The siege''s length is variable, with historians such as Rashid al-Din Hamadani stating that it lasted for seven months, but it is largely agreed that it ended with the defeat and annihilation of the city in April 1221.', 1220, 10, NULL, 1221, 4, NULL, 'month', 'October 1220 – April 1221', 45, 'https://en.wikipedia.org/wiki/Siege_of_Gurganj'),
  ('Q19848817', 'Battle of the Mire', 'The Battle of Tashkent also known as the Battle of the Mire or The Battle of the Marshes took place between the Chagatai Khanate and the forces of Amir Husayn and Timur, and a rare defeat for Timur. In 1365, the Mongols returned under the leadership of Haji Ilyas.', 1365, 5, 22, NULL, NULL, NULL, 'day', '22 May 1365', 37, 'https://en.wikipedia.org/wiki/Battle_of_Tashkent_(1365)'),
  ('Q76995101', 'Siege of Samarkand', 'The sieges of Samarkand (1494-1496) were two failed sieges of Samarkand during the chaotic years of civil war that preceded the fall of the Timurid Empire in 1501.', 1494, NULL, NULL, 1496, NULL, NULL, 'year', '1494–1496', 37, 'https://en.wikipedia.org/wiki/Siege_of_Samarkand_(1490s)'),
  ('Q7510367', 'Siege of Samarkand', 'The siege of Samarkand (1497) was a successful siege by the two armies of Emir Babur of Fergana and Sultan Ali of Bukhara of the city of Samarkand. In May 1497, the city was captured after seven months of siege.', 1497, 5, NULL, NULL, NULL, NULL, 'month', 'May 1497', 41, 'https://en.wikipedia.org/wiki/Siege_of_Samarkand_(1497)'),
  ('Q7510370', 'Siege of Samarkand', 'The siege of Samarkand was the third and last campaign against the city between Mughal and Uzbeks. Four years after its recapture by the forces of Babur, he lost his kingdom and capital following a rebellion.', 1501, NULL, NULL, NULL, NULL, NULL, 'year', '1501', 39, 'https://en.wikipedia.org/wiki/Siege_of_Samarkand_(1501)'),
  ('Q4138186', 'Battle of Ghazdewan', 'The Battle of Ghazdewan occurred near the city of Ghijduvan, what is now Uzbekistan in November 1512 AD between Safavid army, supported by the Mughal Empire, and the Uzbek army.', 1512, 11, 12, NULL, NULL, NULL, 'day', '12 November 1512', 39, 'https://en.wikipedia.org/wiki/Battle_of_Ghazdewan'),
  ('Q65168385', 'Capture of Samarkand by Nader Shah Afshar', 'Nader Shah, the founder of Afsharid dynasty, captured Samarkand (Persian: فتح سمرقند), one of the main political and economic centres of the region, during his Central Asian campaign in 1740. For Nader Shah, who was an admirer of Amir Timur, Samarkand had a symbolic meaning.', 1740, NULL, NULL, NULL, NULL, NULL, 'year', '1740', 39, 'https://en.wikipedia.org/wiki/Capture_of_Samarkand_(1740)'),
  ('Q60791909', 'Siege of Samarkand', 'The siege of Samarkand, or siege of the Samarkand Citadel, was a military engagement fought in the city of Samarkand (in modern-day Uzbekistan) in June 1868. In the engagement, a small garrison of Russian Imperial soldiers was besieged by a combined army of Bukharan soldiers and their allies - including the Kokand Khanate and tributary Turkmen-Uzbek tribes.', 1868, 6, 12, 1868, 6, 18, 'day', '12 June 1868 – 18 June 1868', 34, 'https://en.wikipedia.org/wiki/Siege_of_Samarkand_(1868)'),
  ('Q4065335', '1902 Andijan earthquake', 'The 1902 Andijan earthquake occurred on December 16 with a surface-wave magnitude of 6.4 and a maximum perceived Mercalli intensity of IX (Violent). The city was leveled and over 4,000 people died.', 1902, 12, 16, NULL, NULL, NULL, 'day', '16 December 1902', 39, 'https://en.wikipedia.org/wiki/1902_Andijan_earthquake'),
  ('Q4558717', '1907 Qaratog earthquake', 'The 1907 Qaratog earthquake occurred at 04:23 UTC on 21 October near Qaratog (Karatag) in the border area between Uzbekistan and Tajikistan, then part of the Russian Empire. The shock had an estimated surface-wave magnitude of 7.4 and a maximum felt intensity of IX (Violent) on the Mercalli intensity scale.', 1907, 10, 21, NULL, NULL, NULL, 'day', '21 October 1907', 39, 'https://en.wikipedia.org/wiki/1907_Qaratog_earthquake'),
  ('Q19910623', 'Siege of Khiva', 'The Siege of Khiva was a military operation from 19 January to 19 August 1924 by Basmachi insurgents to conquer the city of Khiva from the Red Army.', 1924, 1, 19, 1924, 1, 24, 'day', '19 January 1924 – 24 January 1924', 34, 'https://en.wikipedia.org/wiki/Siege_of_Khiva_(1924)'),
  ('Q2321680', 'Tashkent Declaration', 'The Tashkent Declaration was signed between India and Pakistan on 10 January 1966 to resolve the Indo-Pakistani War of 1965. Peace was achieved on 23 September through interventions by the Soviet Union and the United States, both of which pushed the two warring countries towards a ceasefire in an attempt to avoid any escalation that could draw in other powers.', 1966, 1, 10, NULL, NULL, NULL, 'day', '10 January 1966', 66, 'https://en.wikipedia.org/wiki/Tashkent_Declaration'),
  ('Q1122110', 'Tajikistani Civil War', 'The Tajikistani Civil War was an armed conflict in Tajikistan that began in May 1992 and ended in June 1997. Regional groups from the Garm and Gorno-Badakhshan regions of Tajikistan rose up against the newly formed government of President Rahmon Nabiyev, which was dominated by people from the Khujand and Kulob regions.', 1992, 5, 5, 1997, 6, 27, 'day', '5 May 1992 – 27 June 1997', 72, 'https://en.wikipedia.org/wiki/Tajikistani_Civil_War'),
  ('Q2945245', 'Uzbekistani presidential term referendum', 'A referendum on extending President Islam Karimov''s term was held in Uzbekistan on 26 March 1995. The proposal would see Karimov remain in office until 2000.', 1995, 3, 26, NULL, NULL, NULL, 'day', '26 March 1995', 37, 'https://en.wikipedia.org/wiki/1995_Uzbek_presidential_term_referendum'),
  ('Q4079409', 'Batken Conflict', 'The Batken conflict (Kyrgyz: Баткен окуясы, romanized: Batken okuyasy, Russian: Баткенские события) was a period of armed clashes between militants of the Islamic Movement of Uzbekistan (IMU) and the Armed Forces of Kyrgyzstan, with support to the former being provided by the Uzbek Ground Forces. It was caused by incursions of IMU militants into Uzbek and Kyrgyz territory from Tajikistan and was in part, centered on the unilateral demarcation of the Kyrgyzstan–Uzbekistan border by Uzbekistan.', 1999, 9, 27, 1999, 9, 27, 'day', '27 September 1999', 48, 'https://en.wikipedia.org/wiki/Batken_conflict'),
  ('Q4456265', '1999 Tashkent bombings', 'The 1999 Tashkent bombings occurred on 16 February when six car bombs exploded in Tashkent, the capital of Uzbekistan. The bombs exploded over the course of an hour and a half, and targeted multiple government buildings.', 1999, 2, 16, NULL, NULL, NULL, 'day', '16 February 1999', 47, 'https://en.wikipedia.org/wiki/1999_Tashkent_bombings'),
  ('Q27627841', 'Tashkent embassy bombings', 'On Friday 30 July 2004, three suicide bombings occurred in Tashkent, Uzbekistan. The bombings targeted the Israeli and American embassies and the office of Uzbekistan''s chief prosecutor.', 2004, 7, 30, NULL, NULL, NULL, 'day', '30 July 2004', 47, 'https://en.wikipedia.org/wiki/2004_Tashkent_suicide_bombings'),
  ('Q764967', 'Andijan massacre', 'On 13 May 2005, protests erupted in Andijan, Uzbekistan. At one point, troops from the Uzbek National Security Service (SNB) fired into a crowd of protesters.', 2005, 5, 13, NULL, NULL, NULL, 'day', '13 May 2005', 61, 'https://en.wikipedia.org/wiki/Andijan_massacre'),
  ('Q501106', '2011 Fergana Valley earthquake', 'The 2011 Fergana Valley earthquake affected Uzbekistan, Kyrgyzstan and Tajikistan at 01:35 KGT (19:35 UTC) on 20 July. The dip-slip shock had a moment magnitude of 6.1 and a maximum Mercalli intensity of VIII (Severe).', 2011, 7, 20, NULL, NULL, NULL, 'day', '20 July 2011', 47, 'https://en.wikipedia.org/wiki/2011_Fergana_Valley_earthquake'),
  ('Q112865573', '2022 Karakalpakstan protests', 'Protests broke out in the autonomous region of Karakalpakstan in Republic of Uzbekistan on 1 July 2022 over proposed amendments by Shavkat Mirziyoyev, the Uzbek President, to the Constitution of Uzbekistan, which would have ended Karakalpakstan''s status as an autonomous region of Uzbekistan and right to secede from Uzbekistan via referendum. A day after protests had begun in the Karakalpak capital of Nukus, President Mirziyoyev withdrew the constitutional amendments.', 2022, 7, 1, NULL, NULL, NULL, 'day', '1 July 2022', 57, 'https://en.wikipedia.org/wiki/2022_Karakalpak_protests');
